<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Invitee extends Model {protected $fillable=['event_id','name','email','phone','identity_key','token','max_guests','rsvp_status','attending_count','dietary','responded_at','attendance_status','attended_count','attendance_confirmed_at','attendance_confirmed_by'];protected $hidden=['token'];protected function casts():array{return ['responded_at'=>'datetime','attendance_confirmed_at'=>'datetime'];}public function event(){return $this->belongsTo(Event::class);}public function deliveries(){return $this->hasMany(Delivery::class);}public function notificationDeliveries(){return $this->hasMany(NotificationDelivery::class);}public function pledge(){return $this->hasOne(Pledge::class);}public function rsvpUrl(){return route('rsvp.show',$this->token);}public function cardUrl(bool $preview=false){$path=$this->event?->invitation_card_path;return route('rsvp.card',['token'=>$this->token,'preview'=>$preview?1:0,'v'=>$path?substr(sha1($path),0,12):null]);} }
